// Organizational Leadership Practice Test 2. Original questions written for Valus from the HOSA 2026–27
// test plan, slightly harder than the sample items. HOSA facts follow the Valus Organizational
// Leadership lessons, which summarize the HOSA Handbook (Sections A–C), the HOSA website and
// The First Fifty Years 1976–2026; parliamentary items follow RONR In Brief.
import {q, mix} from './q.js';
const HB='HOSA Handbook, Sections A–C', WEB='HOSA website (Voting Delegate resources)', FFY='HOSA, The First Fifty Years 1976–2026', BRIEF='Robert’s Rules of Order Newly Revised In Brief';
const VD='Voting Delegate Role and Responsibilities', PP='Parliamentary Procedure', INC='HOSA Inc.', ORG='Organizational Structure of HOSA', HIST='History of HOSA', EC='Positions and Responsibilities of the Executive Council', MEM='Membership';

export default {
 id:'organizational-leadership-2',
 event:'Organizational Leadership',
 title:'Practice Test 2',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'the HOSA Handbook (Sections A–C), the HOSA website, The First Fifty Years 1976–2026 and Robert’s Rules of Order Newly Revised In Brief',
 plan:[{area:VD,weight:24},{area:PP,weight:24},{area:INC,weight:16},{area:ORG,weight:12},{area:HIST,weight:12},{area:EC,weight:8},{area:MEM,weight:4}],
 questions:mix([
  q(VD,'Using HOSA’s allocation table, how many voting delegates does a chartered association with 6,200 members receive?','5',['3','4','6'],'A','3,001–5,000 members earn 4 delegates, and one more is added for each additional 2,000 members, so 5,001–7,000 members earn 5.',HB),
  q(VD,'A chartered association grows from 950 to 1,200 members. How does its number of voting delegates change?','It rises from 2 to 3',['It stays at 2','It rises from 1 to 2','It rises from 3 to 4'],'B','101–1,000 members earn 2 delegates and 1,001–3,000 members earn 3, so crossing 1,000 members adds one delegate.',HB),
  q(VD,'What is the largest number of voting delegates a chartered association can receive under the allocation table?','24',['12','20','30'],'C','The table adds one delegate per 2,000 members above 3,000 and tops out at 24 delegates for 43,001–45,000 members.',HB),
  q(VD,'Which ILC session is listed as one delegates attend only “if desired”?','The Chartered Association Caucus',['The Business Session','Voting Delegate Orientation','The Recognition Session'],'D','Delegates must attend orientation, the Meet the Candidates Breakfast, the Business Session and the Recognition Session; the caucus is attended if desired.',WEB),
  q(VD,'Where are Executive Council applicants’ videos posted for delegates to review before ILC?','On the HOSA website',['In the State Leadership Conference program','On each chapter’s private page','In the Business Session agenda'],'A','Delegates review applicants’ resumes and YouTube videos posted on the HOSA website, along with the Voting Delegate Packet, before ILC.',WEB),
  q(VD,'How are voting delegates who represent their chartered association at ILC recognized?','With a ribbon, certificate and pin',['With a trophy and a scholarship','With a medal at the Business Session','With a plaque mailed to the chapter'],'B','HOSA recognizes voting delegates with a voting delegate ribbon, a certificate and a pin for serving their chartered association.',WEB),
  q(VD,'What is the main purpose of Voting Delegate Orientation at ILC?','To explain procedures and expectations for delegates',['To let candidates give campaign speeches','To conduct the official Executive Council vote','To recognize the year’s competitive event winners'],'C','Orientation prepares delegates for the business session by explaining procedures, expectations and voting instructions.',WEB),
  q(VD,'If the Voting Delegate Test is used, how is a tie between top scorers broken?','The essay question is judged',['A second test is given','The State Advisor chooses','The earlier submission wins'],'D','The Voting Delegate Test has 50 multiple-choice items and one essay question in 60 minutes; the essay is judged only to break ties.',WEB),
  q(VD,'A delegate learns that a candidate from their own state is running. What is the most appropriate approach?','Evaluate every candidate with the same criteria',['Vote for the home-state candidate automatically','Abstain from the election entirely','Promise support before reviewing the materials'],'A','Delegates should use objective criteria such as experience, HOSA knowledge, communication and vision, and avoid regional or personal bias.',WEB),
  q(VD,'Which preparation step should a delegate complete with the Voting Delegate Packet before ILC?','Read it fully and note each item of business',['Wait to open it at the Business Session','Share its confidential items on social media','Return it unopened to HOSA Headquarters'],'B','Careful review of the packet lets delegates make informed decisions and prepare questions instead of voting on first impressions.',WEB),
  q(VD,'During an election, a delegate sees behavior that may violate campaign rules. What should the delegate do?','Report it to the State Advisor or officials',['Confront the candidate during the session','Change their vote to punish the candidate','Ignore it, since rules are not enforced'],'C','Delegates should report possible violations to their State Advisor or appropriate officials rather than handling the problem themselves.',WEB),
  q(VD,'Which of these is the strongest evidence of a candidate’s readiness for office?','A record of leading chapter projects',['The number of giveaways at a booth','Popularity on social media','Being the last candidate met'],'D','Fair evaluation relies on evidence such as past service and accomplishments rather than popularity, gimmicks or how recently a candidate was met.',WEB),
  q(PP,'Which word does Robert’s Rules use for a vote in favor of a motion in a voice vote?','“Aye”',['“Yea”','“Yes”','“Agreed”'],'A','RONR uses “aye” for those in favor and “no” for those opposed; the guidelines’ sample item makes clear that “nay” is not the correct term.',BRIEF),
  q(PP,'Which motion delays a main motion until a specific later meeting?','Postpone to a certain time',['Postpone indefinitely','Lay on the table','Commit or refer'],'B','Postpone to a certain time sets the question aside until a set time; postpone indefinitely kills it and refer sends it to a committee.',BRIEF),
  q(PP,'What vote does a motion to close nominations require under Robert’s Rules?','A two-thirds vote',['A majority vote','Unanimous consent','A majority of members'],'C','Closing nominations limits members’ rights, so it requires two-thirds, though nominations are often closed by general consent.',BRIEF),
  q(PP,'In an election, who counts the ballots and reports the results to the chair?','The tellers',['The candidates','The parliamentarian','The secretary of state'],'D','Tellers count ballots and give their report to the chair, who then declares the result of the election to the assembly.',BRIEF),
  q(PP,'A motion needs a majority vote. The count is 45 yes, 45 no and 10 abstentions. What is the result?','The motion is lost',['The motion is adopted','The chair must declare a recess','The vote is retaken by ballot'],'A','A tie is not a majority, so the motion fails. Abstentions are not votes cast and do not change the outcome.',BRIEF),
  q(PP,'Which motion stops debate and brings the assembly to an immediate vote?','Previous question',['Limit debate','Lay on the table','Orders of the day'],'B','The previous question closes debate and stops amendments. It is undebatable and needs a two-thirds vote because it cuts off members’ rights.',BRIEF),
  q(PP,'A member wants the chair to explain how to make a certain motion. Which request is used?','Parliamentary inquiry',['Point of order','Point of information','Division of the house'],'C','A parliamentary inquiry asks the chair for guidance on procedure, while a request for information asks about facts on the pending question.',BRIEF),
  q(PP,'Which motion is used to repeal an action adopted at an earlier meeting?','Rescind',['Reconsider','Withdraw','Postpone'],'D','Rescind repeals a previous action. It needs two-thirds, a majority with previous notice, or a majority of the entire membership.',BRIEF),
  q(PP,'Which motion requires a second?','Recess',['Point of order','Parliamentary inquiry','Call for the orders of the day'],'A','Recess is a privileged motion that needs a second. Point of order, parliamentary inquiry and orders of the day do not need a second.',BRIEF),
  q(PP,'In the standard order of business, which item comes before new business?','Unfinished business',['Adjournment','Good of the order','Announcements of the next meeting'],'B','Unfinished business and general orders are taken up before new business so that pending matters are settled before new ones arise.',BRIEF),
  q(PP,'Under Robert’s Rules, what vote elects a candidate when the bylaws do not say otherwise?','A majority of votes cast',['A plurality of votes cast','Two-thirds of votes cast','A majority of the membership'],'C','A candidate must receive more than half of the votes cast; if no one does, balloting continues until a candidate wins a majority.',BRIEF),
  q(PP,'A member wants to divide a motion with two unrelated parts so they are voted on separately. Which motion is used?','Division of the question',['Division of the assembly','Withdraw a motion','Objection to consideration'],'D','Division of the question splits a motion into parts. Division of the assembly instead calls for a rising vote to verify a voice vote.',BRIEF),
  q(INC,'Which ranks immediately above the parliamentary authority in an organization’s hierarchy of rules?','Special rules of order',['Standing rules','Bylaws','Laws'],'A','From highest: laws, corporate charter, bylaws, special rules of order, the parliamentary authority, and standing rules and policies.',HB),
  q(INC,'How are bylaws usually amended when they do not state their own procedure?','By two-thirds vote with previous notice',['By a majority vote without notice','By the chair’s ruling alone','By general consent of the board'],'B','Bylaws are fundamental, so changes normally need previous notice and a two-thirds vote, or the procedure the bylaws themselves specify.',HB),
  q(INC,'A rule in HOSA’s bylaws conflicts with Robert’s Rules. Which one applies?','The bylaws',['Robert’s Rules','The rule adopted most recently','Whichever the delegates prefer'],'C','An organization’s bylaws outrank its parliamentary authority, so the bylaw governs whenever the two conflict.',HB),
  q(INC,'Who carries out the daily operations of a nonprofit corporation under the board’s direction?','Staff',['Voting delegates','Event judges','Sponsors'],'D','The board governs and sets direction, while staff, such as HOSA Headquarters staff, carry out daily operations under the board’s direction.',HB),
  q(INC,'What is the purpose of an audit in a nonprofit organization?','An independent review of financial records',['A vote of confidence in the board','A test of members’ knowledge','A review of competitive event scores'],'A','Audits independently check financial records so that funds are managed properly and reported accurately to members and regulators.',HB),
  q(INC,'Which is the best example of ethical governance in a nonprofit?','Transparency about decisions and finances',['Keeping budgets secret from members','Letting one officer approve all spending','Skipping financial reports in busy years'],'B','Ethical governance includes transparency, accountability, conflict-of-interest policies and decisions that serve members.',HB),
  q(INC,'Which item would most likely appear in an organization’s bylaws?','The parliamentary authority',['The menu at the banquet','The hotel room block','The color of conference badges'],'C','Bylaws list the name, purpose, membership, officers, meetings, boards, committees, parliamentary authority and amendment procedure.',HB),
  q(INC,'Why do bylaw amendments usually appear in full in the Voting Delegate Packet?','So delegates can study the exact wording before ILC',['So delegates can rewrite them during orientation','So the chair can adopt them without a vote','So chapters can vote on them by mail'],'D','Delegates may vote on proposed amendments, so reading the exact wording and comparing it with current bylaws in advance matters.',WEB),
  q(ORG,'Which divisions are HOSA’s support divisions rather than active student divisions?','Alumni and professional',['Middle school and secondary','Secondary and postsecondary','Postsecondary and collegiate'],'A','Middle school, secondary and postsecondary/collegiate members are active students; alumni and professional members support them.',HB),
  q(ORG,'At which level are state officers usually elected?','The State Leadership Conference',['The International Leadership Conference','A local chapter meeting','A regional sponsor meeting'],'B','Chartered associations, led by State Advisors and state officers, hold State Leadership Conferences where state officers are often elected.',HB),
  q(ORG,'Who manages HOSA’s international operations such as conferences and communications?','HOSA Headquarters staff',['Chapter advisors','State officers','Event sponsors'],'C','HOSA Headquarters staff manage international operations and support chartered associations, while student officers lead and represent members.',HB),
  q(ORG,'Which organization sponsors the Parliamentary Procedure competitive event?','National Association of Parliamentarians',['National Academy of Sports Medicine','American Red Cross','National Education Association'],'D','HOSA partners with professional organizations that sponsor events, such as NAP for Parliamentary Procedure and NASM for Healthy Living.',WEB),
  q(ORG,'Who usually serves as a local chapter advisor?','A health science teacher',['A State Advisor','An Executive Council officer','A HOSA Headquarters employee'],'A','Local chapters at schools and colleges are guided by chapter advisors, usually health science teachers, and led by student officers.',HB),
  q(ORG,'Which statement best describes how information flows in HOSA?','Both ways, with delegates linking states and HOSA',['Only from members up to Headquarters','Only from sponsors down to chapters','Directly from Headquarters to each member'],'B','Headquarters sends materials such as the Voting Delegate Packet to State Advisors, and members’ views reach the international level through delegates.',HB),
  q(HIST,'HOSA’s 2026 fiftieth anniversary marks its founding in which year?','1976',['1966','1981','1986'],'C','HOSA was founded in 1976 to provide leadership development and career preparation for students in health science education programs.',FFY),
  q(HIST,'Which event change appears in the 2026–27 updates to HOSA’s competitive events?','Research Poster moved to the Teamwork category',['Medical Spelling became a team event','Organizational Leadership was dropped','CPR/First Aid became a solo event'],'D','Each year’s “New for 2026–2027” notes show how events evolve; Research Poster moved to the Teamwork category in 2026–27.',WEB),
  q(HIST,'Which annual conference grew from HOSA’s first conferences into its largest gathering?','The International Leadership Conference',['The State Leadership Conference','The Regional Officer Retreat','The National Health Science Summit'],'A','HOSA’s first conferences grew into today’s International Leadership Conference, where chartered associations send competitors and voting delegates.',FFY),
  q(HIST,'HOSA’s broader name reflects a focus on what?','All health careers',['Only nursing careers','Only hospital careers','Only medical school'],'B','The name HOSA-Future Health Professionals reflects HOSA’s broad focus on preparing students for the full range of health careers.',FFY),
  q(HIST,'Which identity item states that HOSA empowers members through education, collaboration and experience?','The mission',['The motto','The creed','The emblem'],'C','HOSA’s mission is to empower HOSA-Future Health Professionals to become leaders in the global health community through education, collaboration and experience.',HB),
  q(HIST,'Which HOSA program supports members’ education beyond competition?','Scholarships',['Sponsorship fees','Event dress codes','Delegate quotas'],'D','HOSA’s programs grew to include competitive events, leadership development, service projects, scholarships and recognition programs.',FFY),
  q(EC,'Which Executive Council officer presides when the president is absent?','The vice president',['The secretary','The parliamentarian','The State Advisor'],'A','Under general RONR officer duties, the vice president assists the president and presides in the president’s absence.',BRIEF),
  q(EC,'Where are Executive Council officers elected?','At ILC, with voting delegates',['At each State Leadership Conference','By HOSA Headquarters staff','By an online vote of all members'],'B','Executive Council officers are elected at ILC with the participation of voting delegates and serve a one-year term.',HB),
  q(EC,'Which is a typical responsibility of an Executive Council officer?','Representing members and promoting HOSA',['Judging every competitive event at ILC','Setting each chapter’s dues amount','Selecting each state’s voting delegates'],'C','Officers represent members, promote HOSA, help lead conference activities, communicate with chartered associations and model leadership.',HB),
  q(EC,'Where should a delegate find the exact titles and duties of Executive Council positions?','The HOSA Handbook and bylaws',['A candidate’s campaign flyer','A sponsor’s website','A chapter newsletter'],'D','The specific titles and duties of Executive Council positions are listed in the HOSA Handbook and bylaws and should be learned exactly as written.',HB),
  q(MEM,'Why does a chartered association’s accurate membership count matter at ILC?','It sets the number of voting delegates',['It sets the number of Executive Council seats','It decides who hosts ILC','It sets each member’s event scores'],'A','A chartered association’s membership size determines its number of voting delegates, so accurate affiliation affects its voice at ILC.',HB),
  q(MEM,'Which members are eligible to compete in Organizational Leadership?','Secondary and postsecondary/collegiate',['Middle school and secondary only','Alumni and professional members','All divisions, including alumni'],'B','Organizational Leadership is open to secondary and postsecondary/collegiate members, and they must be properly affiliated to compete.',WEB)
 ],3927)
};
